import numpy as np

def read_xyz(fn):
    with open(fn) as f:
        lines = f.read().strip().split('\n')
    n = int(lines[0])
    els, coords = [], []
    for ln in lines[2:2+n]:
        p = ln.split()
        els.append(p[0]); coords.append([float(x) for x in p[1:4]])
    return els, np.array(coords)

els, X = read_xyz('optimized.xyz')
print(len(els), "atoms; formula:", {e: els.count(e) for e in sorted(set(els))})

# Tc is atom 0
tc = X[0]
print("\nDistances from Tc:")
for i in range(1, len(els)):
    d = np.linalg.norm(X[i]-tc)
    if d < 3.0:
        print(f"  Tc-{els[i]}{i}: {d:.3f} A")

# S-C and P-C bonds
print("\nS-C bonds:")
for i,e in enumerate(els):
    if e=='S':
        for j,f2 in enumerate(els):
            if f2=='C':
                d = np.linalg.norm(X[i]-X[j])
                if d < 2.0: print(f"  S{i}-C{j}: {d:.3f} A")
print("\nP-C bonds (count per P):")
for i,e in enumerate(els):
    if e=='P':
        cnt = [(j, round(np.linalg.norm(X[i]-X[j]),3)) for j,f2 in enumerate(els) if f2=='C' and np.linalg.norm(X[i]-X[j])<2.1]
        print(f"  P{i}: {cnt}")
print("\nC-C bonds (linkers):")
for i in range(len(els)):
    for j in range(i+1,len(els)):
        if els[i]=='C' and els[j]=='C':
            d = np.linalg.norm(X[i]-X[j])
            if d < 1.7: print(f"  C{i}-C{j}: {d:.3f} A")

# S-Tc-S angle (should be ~90, cis)
sidx = [i for i,e in enumerate(els) if e=='S']
v1 = X[sidx[0]]-tc; v2 = X[sidx[1]]-tc
ang = np.degrees(np.arccos(np.dot(v1,v2)/np.linalg.norm(v1)/np.linalg.norm(v2)))
print(f"\nS-Tc-S angle: {ang:.1f} deg (expect ~90, cis)")
